# 背景画像をキャッシュ（デコードは一度だけ）
@st.cache_data
def _load_bg_image():
    from PIL import Image
    import io, base64
    img_data = base64.b64decode(PDF_BG_IMAGE)
    return Image.open(io.BytesIO(img_data)).convert("RGB")

@st.cache_data(show_spinner=False)
def generate_island_image(diff_map_tuple, machine_map_tuple=(), date_key="", as_pdf=False, mode="diff", caption="", targets=(), recommendations=()):
    """PILで高速に差枚+機種名オーバーレイ画像を生成（キャッシュ付き）"""
    from PIL import Image, ImageDraw, ImageFont
    import io

    diff_map = dict(diff_map_tuple)
    machine_map = dict(machine_map_tuple)

    # 背景をコピー
    bg = _load_bg_image().copy()
    W, H = bg.size
    draw = ImageDraw.Draw(bg)

    # フォント（日本語対応 - 複数パスを試行）
    FONT_SIZE = 17
    FONT_SM = 13
    JP_FONT_PATHS = [
        "/usr/share/fonts/opentype/ipafont-gothic/ipag.ttf",
        "/usr/share/fonts/opentype/ipaexfont-gothic/ipaexg.ttf",
        "/usr/share/fonts/truetype/fonts-japanese-gothic.ttf",
        "/usr/share/fonts/opentype/noto/NotoSansCJK-Bold.ttc",
        "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",
        "fonts/ipag.ttf",  # リポジトリ同梱用
    ]
    font = None
    font_sm = None
    for fp in JP_FONT_PATHS:
        try:
            import os
            if not os.path.exists(fp): continue
            kw = {"index": 0} if fp.endswith(".ttc") else {}
            font    = ImageFont.truetype(fp, FONT_SIZE, **kw)
            font_sm = ImageFont.truetype(fp, FONT_SM,   **kw)
            break
        except: continue
    if font is None:
        font    = ImageFont.load_default()
        font_sm = font

    def get_color(diff):
        if diff >= 10000: return (17, 17, 17)
        if diff >= 5000:  return (139, 0, 0)
        if diff >= 4000:  return (204, 0, 0)
        if diff >= 3000:  return (180, 50, 180)
        if diff >= 2000:  return (80, 160, 60)
        if diff >= 1000:  return (180, 180, 0)
        if diff > 0:      return (100, 180, 220)
        if diff == 0:     return (200, 200, 200)
        return (255, 255, 255)  # マイナスは白背景

    def get_text_color(diff):
        if diff < 0: return (220, 0, 0)
        if diff >= 1000: return (255, 255, 255)
        return (40, 40, 40)

    def get_outline_color(diff):
        if diff < 0: return (220, 0, 0)
        return (200, 200, 200)

    # 回転数モード用のカラー
    def get_color_rot(v):
        if v >= 8000: return (139, 0, 0)      # 激熱
        if v >= 7000: return (204, 0, 0)
        if v >= 6000: return (230, 120, 0)
        if v >= 5000: return (80, 160, 60)
        if v >= 4000: return (180, 180, 0)
        if v >= 2000: return (100, 180, 220)
        return (238, 238, 238)                 # 低回転

    def get_text_color_rot(v):
        if v >= 5000: return (255, 255, 255)
        return (40, 40, 40)

    if mode == "rot":
        get_color = get_color_rot
        get_text_color = get_text_color_rot
        get_outline_color = lambda v: (150, 150, 150)

    BW = 56
    BH = 20

    # キャプション（左上に表示期間などを焼き込み）
    if caption:
        try:
            cap_font = ImageFont.truetype(JP_FONT_PATHS[0], 30) if font else font
        except Exception:
            cap_font = font
        draw.rectangle([10, 8, 620, 52], fill=(255, 255, 255))
        draw.text((18, 14), caption, fill=(0, 0, 0), font=cap_font)

    for num, (rx, ry) in PDF_POSITIONS.items():
        diff = diff_map.get(num)
        px = int(rx * W)
        py = int(ry * H)
        # 数値が欠損・非表示でも機種名は描画する。
        if diff is not None and pd.notna(diff) and np.isfinite(diff):
            diff = float(diff)
            color = get_color(diff)
            outline_c = get_outline_color(diff)

            # 差枚バッジ（台番の上にずらして台番が見えるように）
            SHIFT = 18  # 上にずらすピクセル数
            x0, y0 = px - BW//2, py - BH//2 - SHIFT
            x1, y1 = px + BW//2, py + BH//2 - SHIFT
            draw.rectangle([x0, y0, x1, y1], fill=color)
            draw.rectangle([x0, y0, x1, y1], outline=outline_c, width=1)

            if mode == "rot":
                text = f"{int(diff):,}"
            else:
                text = f"+{int(diff):,}" if diff > 0 else ("0" if diff == 0 else f"{int(diff):,}")
            text_color = get_text_color(diff)
            try:
                bbox = draw.textbbox((0, 0), text, font=font)
                tw = bbox[2] - bbox[0]
                th = bbox[3] - bbox[1]
            except:
                tw, th = len(text) * 9, FONT_SIZE
            draw.text((px - tw//2, py - th//2 - SHIFT), text, fill=text_color, font=font)

        # 機種名（バッジの下）
        machine = machine_map.get(num, "")
        if machine:
            short = shorten_name(machine)
            try:
                mbbox = draw.textbbox((0, 0), short, font=font_sm)
                mw = mbbox[2] - mbbox[0]
                mh = mbbox[3] - mbbox[1]
            except:
                mw, mh = len(short) * 7, FONT_SM
            mx0 = px - mw//2 - 1
            my0 = py + BH//2 + 2
            mx1 = px + mw//2 + 1
            my1 = my0 + mh + 2
            draw.rectangle([mx0, my0, mx1, my1], fill=(255, 255, 255))
            draw.text((px - mw//2, my0 + 1), short, fill=(50, 50, 50), font=font_sm)

    # おすすめ枠と星（フォントに依存しない五角星）
    import math
    for num in recommendations:
        if num not in PDF_POSITIONS:
            continue
        rx, ry = PDF_POSITIONS[num]
        px, py = int(rx * W), int(ry * H)
        orange = (255, 140, 0)
        draw.rectangle([px-29, py-29, px+29, py+27], outline=orange, width=3)
        cx, cy = px+23, py+22
        points = []
        for i in range(10):
            angle = -math.pi/2 + i*math.pi/5
            radius = 10 if i % 2 == 0 else 4.5
            points.append((cx+radius*math.cos(angle), cy+radius*math.sin(angle)))
        draw.polygon(points, fill=orange, outline=(110, 60, 0))

    # ── 狙い台マーキング（優先順にピンク枠＋番号） ──
    MARK_COLOR = (255, 0, 150)
    for rank, tnum in enumerate(targets, start=1):
        if tnum not in PDF_POSITIONS:
            continue
        rx, ry = PDF_POSITIONS[tnum]
        px, py = int(rx * W), int(ry * H)
        mx0, my0 = px - 32, py - 32
        mx1, my1 = px + 32, py + 30
        draw.rectangle([mx0, my0, mx1, my1], outline=MARK_COLOR, width=3)
        # 優先順位の丸数字
        r = 13
        cx, cy = mx0, my0
        draw.ellipse([cx - r, cy - r, cx + r, cy + r], fill=MARK_COLOR)
        rt = str(rank)
        try:
            rb = draw.textbbox((0, 0), rt, font=font)
            rw, rh = rb[2] - rb[0], rb[3] - rb[1]
        except Exception:
            rw, rh = 8, 12
        draw.text((cx - rw // 2, cy - rh // 2 - 1), rt, fill=(255, 255, 255), font=font)

    buf = io.BytesIO()
    bg_rgb = bg.convert("RGB")
    if as_pdf:
        bg_rgb.save(buf, format="PDF", resolution=200)
    else:
        bg_rgb.save(buf, format="PNG", optimize=True)
    return buf.getvalue()


def at_most_1000_in_three_days(num, history, dates):
    """店舗共通の最新3日を判定。欠損・非有限値は対象外。"""
    days = sorted(set(dates), reverse=True)[:3]
    if len(days) != 3 or pd.isna(num):
        return False
    daily = history.get(int(num), {})
    values = [daily.get(day, {}).get("diff", np.nan) for day in days]
    return all(pd.notna(v) and np.isfinite(v) and v <= 1000 for v in values)


def process_df(df_raw):
    df = pd.DataFrame()
    cols = {c.strip(): c for c in df_raw.columns}
    def fc(*keys):
        for k in keys:
            for c in cols:
                if k in c: return cols[c]
        return None
    台番col = fc("台番", "台no", "No")
    機種col = fc("機種名", "機種", "name")
    差枚col = fc("差枚", "前日差枚")
    回転col = fc("回転数", "回転", "G数", "ゲーム数")
    ボーナスcol = fc("ボーナス", "bonus")
    if not 台番col or not 機種col: return None
    df["台番"] = df_raw[台番col].apply(parse_num)
    df["機種名"] = df_raw[機種col].astype(str).str.strip()
    df["前日差枚"] = df_raw[差枚col].apply(parse_num) if 差枚col else np.nan
    df["回転数"] = df_raw[回転col].apply(parse_num) if 回転col else np.nan
    df["ボーナス"] = df_raw[ボーナスcol].apply(parse_num) if ボーナスcol else np.nan
    df["週平均"] = df["前日差枚"]
    df["is_juggler"] = df["機種名"].apply(is_juggler)
    # 欠損行による上書きを防ぐ。0は有効な値として扱う。
    df = df[np.isfinite(df["台番"]) & (df["台番"] % 1 == 0)].copy()
    df["台番"] = df["台番"].astype(int)
    df["_valid_count"] = df[["前日差枚", "回転数"]].notna().sum(axis=1)
    df = (df.sort_values("_valid_count", kind="stable")
            .drop_duplicates("台番", keep="last")
            .drop(columns="_valid_count")
            .sort_index().reset_index(drop=True))
    return df

@st.cache_data(ttl=300)
def load_today():
    try:
        client = get_gspread_client()
        sp = client.open_by_key(SPREADSHEET_ID)
        sheets = sorted(
            [ws for ws in sp.worksheets() if re.match(r"\d{4}-\d{2}-\d{2}", ws.title)],
            key=lambda ws: ws.title, reverse=True
        )
        if not sheets: return None, None
        ws = sheets[0]
        data = ws.get_all_records()
        if not data: return None, None
        df = pd.DataFrame(data)
        result = process_df(df)
        if result is None: return None, None
        return result, ws.title
    except Exception as e:
        st.error(f"データ読み込みエラー: {e}")
        return None, None

@st.cache_data(ttl=60)
def list_sheet_titles():
    """診断用: スプレッドシートの全シート名"""
    client = get_gspread_client()
    sp = client.open_by_key(SPREADSHEET_ID)
    return [ws.title for ws in sp.worksheets()]

@st.cache_data(ttl=300)
def load_history(max_days=10):
    try:
        client = get_gspread_client()
        spreadsheet = client.open_by_key(SPREADSHEET_ID)
        all_ws = spreadsheet.worksheets()
        date_sheets = [ws for ws in all_ws if re.match(r"\d{4}-\d{2}-\d{2}", ws.title)]
        date_sheets = sorted(date_sheets, key=lambda w: w.title, reverse=True)[:max_days]
        history = {}
        date_labels = [ws.title for ws in date_sheets]
        for ws in date_sheets:
            try:
                data = ws.get_all_records()
                if not data: continue
                raw = pd.DataFrame(data)
                # 履歴も前日と同じ正規化・重複排除を適用する。
                if not any("機種" in str(c) or "name" in str(c) for c in raw.columns):
                    raw["機種名"] = ""
                daily = process_df(raw)
                if daily is None: continue
                for _, row in daily.iterrows():
                    num = int(row["台番"])
                    history.setdefault(num, {})[ws.title] = {
                        "diff": row["前日差枚"], "rot": row["回転数"]}
            except: continue
        return history, date_labels
    except Exception as e:
        # 失敗をキャッシュさせないためraise（呼び出し側で警告表示）
        raise

